	    // Other keywords:
	    // <https://www.php.net/manual/en/reserved.php>
	    // <https://www.php.net/manual/en/language.types.type-juggling.php>
	    "array",
	    "abstract",
	    "and",
	    "as",
	    "binary",
	    "bool",
	    "boolean",
	    "break",
	    "callable",
	    "case",
	    "catch",
	    "class",
	    "clone",
	    "const",
	    "continue",
	    "declare",
	    "default",
	    "do",
	    "double",
	    "else",
	    "elseif",
	    "empty",
	    "enddeclare",
	    "endfor",
	    "endforeach",
	    "endif",
	    "endswitch",
	    "endwhile",
	    "enum",
	    "eval",
	    "extends",
	    "final",
	    "finally",
	    "float",
	    "for",
	    "foreach",
	    "from",
	    "global",
	    "goto",
	    "if",
	    "implements",
	    "instanceof",
	    "insteadof",
	    "int",
	    "integer",
	    "interface",
	    "isset",
	    "iterable",
	    "list",
	    "match|0",
	    "mixed",
	    "new",
	    "never",
	    "object",
	    "or",
	    "private",
	    "protected",
	    "public",
	    "readonly",
	    "real",
	    "return",
	    "string",
	    "switch",
	    "throw",
	    "trait",
	    "try",
	    "unset",
	    "use",
	    "var",
	    "void",
	    "while",
	    "xor",
	    "yield"
